import type { TypeValidator } from "./type-validator";

/**
 * Framework-agnostic route location representation.
 */
export interface RouteLocation<TState = unknown> {
  pathname: string;
  search: string;
  hash: string;
  query: Record<string, string | string[] | undefined>;
  state: Readonly<Partial<TState>> | null;
}

/**
 * Lazy file route reference generated by filesystem-routing.
 */
export interface FileRouteLazyRef<M = Record<string, unknown>> {
  src: string;
  import(): Promise<M>;
}

/**
 * Eager file route reference generated by filesystem-routing.
 */
export interface FileRouteEagerRef<M = Record<string, unknown>> {
  src?: string;
  require(): M;
}

/**
 * Route manifest entry generated by filesystem-routing.
 */
export interface FileRouteEntry {
  path: string;
  page?: boolean;
  $component?: FileRouteLazyRef | FileRouteEagerRef;
  $$route?: FileRouteEagerRef;
  children?: readonly FileRouteEntry[];
  [key: string]: unknown;
}

/**
 * Route configuration defining schemas, preloading, and error handling.
 */
export interface RouteConfig<
  TParams = unknown,
  TSearch = unknown,
  TState = unknown,
  THash = unknown,
  TData = unknown,
  TLocation = RouteLocation<TState>,
> {
  params?: TypeValidator<TParams>;
  search?: TypeValidator<TSearch>;
  state?: TypeValidator<TState>;
  hash?: TypeValidator<THash>;
  preload?: (args: { params: TParams; search: TSearch; location: TLocation }) => TData;
  onError?: (args: {
    error: RouteValidationError;
    rawParams: Record<string, string | undefined>;
    rawSearch: Record<string, unknown>;
  }) => void;
  info?: Record<string, unknown>;
}

/**
 * Framework-agnostic route definition object wrapping validated route configuration.
 */
export interface DefinedRouteConfig<
  TParams = unknown,
  TSearch = unknown,
  TState = unknown,
  THash = unknown,
  TData = unknown,
  TLocation = RouteLocation<TState>,
> {
  readonly config: RouteConfig<TParams, TSearch, TState, THash, TData, TLocation>;
}

/**
 * Error thrown on route validation failure.
 */
export class RouteValidationError extends Error {
  public readonly target: "params" | "search" | "state" | "hash";
  public readonly issues: ReadonlyArray<{ message: string; path?: string }>;

  public constructor(
    target: "params" | "search" | "state" | "hash",
    issues: ReadonlyArray<{ message: string; path?: string }>,
  ) {
    super(`Route validation failed for ${target}: ${issues.map((i) => i.message).join("; ")}`);
    this.name = "RouteValidationError";
    this.target = target;
    this.issues = issues;
  }
}